import { DurableObject } from "cloudflare:workers";

const KICK_AUTHORIZE_URL = "https://id.kick.com/oauth/authorize";
const KICK_TOKEN_URL = "https://id.kick.com/oauth/token";
const KICK_REVOKE_URL = "https://id.kick.com/oauth/revoke";
const KICK_USERS_URL = "https://api.kick.com/public/v1/users";
const KICK_PUBLIC_KEY_URL = "https://api.kick.com/public/v1/public-key";
const KICK_EVENT_SUBSCRIPTIONS_URL = "https://api.kick.com/public/v1/events/subscriptions";
const KICK_CHANNELS_URL = "https://api.kick.com/public/v1/channels";
const KICK_CATEGORIES_URL = "https://api.kick.com/public/v2/categories";

const KICK_WEBHOOK_PATH = "/kick/webhook";
const KICK_CONNECT_PAGE_PATH = "/connect/kick";
const REALTIME_WEBSOCKET_PATH = "/realtime/connect";
const REALTIME_STATUS_PATH = "/realtime/status";
const REALTIME_CONNECTION_ID_HEADER = "X-SleepySource-Connection-Id";
const REALTIME_CONNECTION_TOKEN_HEADER = "X-SleepySource-Connection-Token";
const SLEEPYSOURCE_LOGO_DATA_URI = "data:image/webp;base64,";

const REFRESH_EARLY_SECONDS = 300;
const REFRESH_LOCK_SECONDS = 30;
const EVENT_DELIVERY_LEASE_SECONDS = 45;
const EVENT_DELIVERY_DEFAULT_LIMIT = 10;
const EVENT_DELIVERY_MAX_LIMIT = 25;

const KICK_SCOPES = [
  "user:read",
  "channel:read",
  "channel:write",
  "events:subscribe",
];

const SLEEPYSOURCE_BASE_EVENTS = [
  { name: "chat.message.sent", version: 1 },
  { name: "channel.followed", version: 1 },
  { name: "channel.subscription.renewal", version: 1 },
  { name: "channel.subscription.gifts", version: 1 },
  { name: "channel.subscription.new", version: 1 },
  { name: "kicks.gifted", version: 1 },
  { name: "channel.reward.redemption.updated", version: 1 },
];

let schemaReadyPromise = null;
let kickPublicKeyCache = null;
let kickPublicKeyCachedAt = 0;
const KICK_PUBLIC_KEY_CACHE_SECONDS = 21600;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    try {
      if (url.pathname === "/health") {
        return await handleHealth(env);
      }

      if (url.pathname === KICK_CONNECT_PAGE_PATH) {
        return await handleKickConnectPage(request, env, url);
      }

      if (url.pathname === "/oauth/kick/start") {
        return await handleOAuthStart(request, env);
      }

      if (url.pathname === "/oauth/kick/status") {
        return await handleOAuthStatus(request, env);
      }

      if (url.pathname === "/oauth/kick/callback") {
        return await handleOAuthCallback(request, env, url);
      }

      if (url.pathname === "/kick/connection/status") {
        return await handleConnectionStatus(request, env);
      }

      if (url.pathname === "/kick/connection/refresh") {
        return await handleConnectionRefresh(request, env);
      }

      if (url.pathname === "/kick/connection/disconnect") {
        return await handleConnectionDisconnect(request, env);
      }

      if (url.pathname === "/kick/channel/metadata") {
        return await handleChannelMetadata(request, env);
      }

      if (url.pathname === "/kick/categories/search") {
        return await handleCategorySearch(request, env);
      }

      if (url.pathname === "/kick/channel/update") {
        return await handleChannelUpdate(request, env);
      }

      if (url.pathname === "/kick/events/status") {
        return await handleEventSubscriptionsStatus(request, env);
      }

      if (url.pathname === "/kick/events/sync") {
        return await handleEventSubscriptionsSync(request, env);
      }

      if (url.pathname === "/kick/events/delivery/poll") {
        return await handleEventDeliveryPoll(request, env);
      }

      if (url.pathname === "/kick/events/delivery/ack") {
        return await handleEventDeliveryAck(request, env);
      }

      if (url.pathname === REALTIME_WEBSOCKET_PATH) {
        return await handleRealtimeConnect(request, env);
      }

      if (url.pathname === REALTIME_STATUS_PATH) {
        return await handleRealtimeStatus(request, env);
      }

      if (url.pathname === KICK_WEBHOOK_PATH) {
        return await handleKickWebhook(request, env);
      }

      return new Response("SleepySource API is online.", {
        status: 200,
        headers: {
          "Content-Type": "text/plain; charset=utf-8",
          "Cache-Control": "no-store",
        },
      });
    } catch (error) {
      console.error("Unhandled Worker error:", safeErrorMessage(error));
      return jsonError("internal_server_error", 500);
    }
  },
};

// ================================================================
// HEALTH
// ================================================================

async function handleHealth(env) {
  let databaseSchemaConfigured = false;

  if (env.DB) {
    try {
      await ensureSchema(env);
      databaseSchemaConfigured = true;
    } catch (error) {
      console.error("Schema check failed:", safeErrorMessage(error));
    }
  }

  return Response.json(
    {
      status: "ok",
      service: "SleepySource API",
      kickClientIdConfigured: Boolean(env.KICK_CLIENT_ID),
      kickClientSecretConfigured: Boolean(env.KICK_CLIENT_SECRET),
      kickRedirectUriConfigured: Boolean(env.KICK_REDIRECT_URI),
      tokenEncryptionKeyConfigured: Boolean(env.TOKEN_ENCRYPTION_KEY),
      databaseConfigured: Boolean(env.DB),
      persistentConnectionStoreConfigured: databaseSchemaConfigured,
      automaticTokenRefreshEnabled: true,
      disconnectRevokeEnabled: true,
      webhookReceiverEnabled: true,
      webhookSignatureVerificationEnabled: true,
      eventSubscriptionManagementEnabled: true,
      baselineEventSubscriptionCount: SLEEPYSOURCE_BASE_EVENTS.length,
      reliableEventQueueEnabled: true,
      eventAcknowledgementEnabled: true,
      eventDeliveryLeaseSeconds: EVENT_DELIVERY_LEASE_SECONDS,
      eventDeliveryMaxBatch: EVENT_DELIVERY_MAX_LIMIT,
      realtimeBindingConfigured: Boolean(env.REALTIME),
      realtimeWebSocketEnabled: Boolean(env.REALTIME),
      realtimeHibernationEnabled: Boolean(env.REALTIME),
      realtimeFallbackQueueEnabled: true,
      realtimeWebSocketUrl: `wss://sleepysource-api.sleepyservices.workers.dev${REALTIME_WEBSOCKET_PATH}`,
      kickWebhookUrl: `https://sleepysource-api.sleepyservices.workers.dev${KICK_WEBHOOK_PATH}`,
      kickRedirectUri: env.KICK_REDIRECT_URI || null,
    },
    { headers: noStoreHeaders() }
  );
}

// ================================================================
// OAUTH START
// ================================================================

async function handleOAuthStart(request, env) {
  if (request.method !== "GET" && request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!isConfigured(env)) {
    return jsonError("server_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const now = unixNow();
    const expiresAt = now + 600;
    const sessionId = crypto.randomUUID();
    const connectionId = crypto.randomUUID();
    const state = randomBase64Url(32);
    const codeVerifier = randomBase64Url(64);
    const pollToken = randomBase64Url(32);
    const pollTokenHash = await sha256Base64Url(pollToken);

    await env.DB.prepare(
      `
      DELETE FROM oauth_sessions
      WHERE expires_at < ?
        AND (
          status != 'completed'
          OR completed_at < ?
        )
      `
    )
      .bind(now, now - 86400)
      .run();

    await env.DB.prepare(
      `
      INSERT INTO oauth_sessions (
        session_id,
        connection_id,
        state,
        code_verifier,
        poll_token_hash,
        status,
        created_at,
        expires_at
      )
      VALUES (?, ?, ?, ?, ?, 'pending', ?, ?)
      `
    )
      .bind(
        sessionId,
        connectionId,
        state,
        codeVerifier,
        pollTokenHash,
        now,
        expiresAt
      )
      .run();

    // The desktop intentionally receives the branded Cloudflare connection page
    // as authorize_url. This preserves compatibility with existing desktop release
    // clients while ensuring the user sees SleepySource before being sent to Kick.
    const connectUrl = new URL(KICK_CONNECT_PAGE_PATH, request.url);
    connectUrl.searchParams.set("session_id", sessionId);

    return Response.json(
      {
        status: "pending",
        session_id: sessionId,
        poll_token: pollToken,
        authorize_url: connectUrl.toString(),
        connect_url: connectUrl.toString(),
        expires_in: 600,
      },
      { headers: noStoreHeaders() }
    );
  } catch (error) {
    console.error("OAuth start failed:", safeErrorMessage(error));
    return jsonError("oauth_start_failed", 500);
  }
}

async function handleKickConnectPage(request, env, url) {
  if (request.method !== "GET") {
    return htmlMessage("SleepyServices", "Invalid connection request.", false, 405);
  }

  if (!isConfigured(env)) {
    return htmlMessage(
      "SleepyServices is not ready",
      "The hosted Kick connection service is not configured correctly.",
      false,
      500
    );
  }

  const sessionId = cleanCredential(url.searchParams.get("session_id"), 128);
  if (!sessionId) {
    return htmlMessage(
      "Connection link is incomplete",
      "Return to the app and choose Connect with Kick again.",
      false,
      400
    );
  }

  try {
    await ensureSchema(env);
    const now = unixNow();
    const session = await env.DB.prepare(
      `
      SELECT
        session_id,
        state,
        code_verifier,
        status,
        error_code,
        expires_at
      FROM oauth_sessions
      WHERE session_id = ?
      LIMIT 1
      `
    )
      .bind(sessionId)
      .first();

    if (!session) {
      return htmlMessage(
        "Connection link expired",
        "This connection connection link is no longer valid. Return to the app and try again.",
        false,
        400
      );
    }

    if (session.status === "completed") {
      return htmlMessage(
        "Kick already connected",
        "This authorization has already completed. You can close this window and Return to the app.",
        true,
        200
      );
    }

    if (session.status === "processing") {
      return htmlMessage(
        "Finishing your connection",
        "Kick approval was received and the secure connection is being finalized. Return to the app in a moment.",
        true,
        200
      );
    }

    if (session.status === "failed") {
      return htmlMessage(
        "Connection needs another try",
        "This authorization attempt could not be completed. Return to the app and choose Connect with Kick again.",
        false,
        400
      );
    }

    if (session.status !== "pending" || Number(session.expires_at) < now) {
      if (session.status === "pending") {
        await markSessionFailed(env, session.session_id, "session_expired");
      }
      return htmlMessage(
        "Connection link expired",
        "Return to the app and choose Connect with Kick again.",
        false,
        400
      );
    }

    const codeVerifier = cleanCredential(session.code_verifier, 256);
    const state = cleanCredential(session.state, 256);
    if (!codeVerifier || !state) {
      await markSessionFailed(env, session.session_id, "invalid_session_state");
      return htmlMessage(
        "Connection could not start",
        "SleepyServices could not prepare this authorization session. Return to the app and try again.",
        false,
        500
      );
    }

    const codeChallenge = await sha256Base64Url(codeVerifier);
    const authorizeUrl = buildKickAuthorizeUrl(env, state, codeChallenge);
    const remainingSeconds = Math.max(1, Number(session.expires_at) - now);
    return kickConnectPage(authorizeUrl.toString(), remainingSeconds);
  } catch (error) {
    console.error("Kick connect page failed:", safeErrorMessage(error));
    return htmlMessage(
      "Connection page unavailable",
      "SleepyServices could not open the secure Kick connection page. Return to the app and try again.",
      false,
      500
    );
  }
}

function buildKickAuthorizeUrl(env, state, codeChallenge) {
  const authorizeUrl = new URL(KICK_AUTHORIZE_URL);
  authorizeUrl.searchParams.set("response_type", "code");
  authorizeUrl.searchParams.set("client_id", env.KICK_CLIENT_ID);
  authorizeUrl.searchParams.set("redirect_uri", env.KICK_REDIRECT_URI);
  authorizeUrl.searchParams.set("scope", KICK_SCOPES.join(" "));
  authorizeUrl.searchParams.set("state", state);
  authorizeUrl.searchParams.set("code_challenge", codeChallenge);
  authorizeUrl.searchParams.set("code_challenge_method", "S256");
  return authorizeUrl;
}

// ================================================================
// OAUTH STATUS
// ================================================================

async function handleOAuthStatus(request, env) {
  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!env.DB) {
    return jsonError("server_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const body = await readJson(request);
    if (!body) {
      return jsonError("invalid_json", 400);
    }

    const sessionId = cleanCredential(body.session_id, 128);
    const pollToken = cleanCredential(body.poll_token, 512);

    if (!sessionId || !pollToken) {
      return jsonError("missing_credentials", 400);
    }

    const pollTokenHash = await sha256Base64Url(pollToken);
    const now = unixNow();

    const session = await env.DB.prepare(
      `
      SELECT
        session_id,
        connection_id,
        status,
        error_code,
        expires_at,
        completed_at
      FROM oauth_sessions
      WHERE session_id = ?
        AND poll_token_hash = ?
      LIMIT 1
      `
    )
      .bind(sessionId, pollTokenHash)
      .first();

    if (!session) {
      return jsonError("invalid_session_credentials", 401);
    }

    if (session.status === "pending") {
      if (Number(session.expires_at) < now) {
        await env.DB.prepare(
          `
          UPDATE oauth_sessions
          SET
            status = 'failed',
            error_code = 'session_expired',
            code_verifier = '',
            completed_at = ?
          WHERE session_id = ?
            AND status = 'pending'
          `
        )
          .bind(now, sessionId)
          .run();

        return Response.json(
          { status: "failed", error: "session_expired" },
          { headers: noStoreHeaders() }
        );
      }

      return Response.json(
        { status: "pending" },
        { headers: noStoreHeaders() }
      );
    }

    if (session.status === "processing") {
      return Response.json(
        { status: "processing" },
        { headers: noStoreHeaders() }
      );
    }

    if (session.status === "failed") {
      return Response.json(
        {
          status: "failed",
          error: session.error_code || "connection_failed",
        },
        { headers: noStoreHeaders() }
      );
    }

    if (session.status === "completed") {
      const connection = await loadConnection(env, session.connection_id);

      if (!connection) {
        return jsonError("connection_record_missing", 500);
      }

      await upsertConnectionCredential(
        env,
        session.connection_id,
        pollTokenHash,
        now
      );

      if (connection.revoked_at != null) {
        return Response.json(
          { status: "disconnected" },
          { headers: noStoreHeaders() }
        );
      }

      return Response.json(
        {
          status: "completed",
          connection: publicConnection(connection),
          persistent_connection_ready: true,
        },
        { headers: noStoreHeaders() }
      );
    }

    return jsonError("unknown_session_status", 500);
  } catch (error) {
    console.error("OAuth status failed:", safeErrorMessage(error));
    return jsonError("status_check_failed", 500);
  }
}

// ================================================================
// OAUTH CALLBACK
// ================================================================

async function handleOAuthCallback(request, env, url) {
  if (request.method !== "GET") {
    return htmlMessage("SleepyServices", "Invalid OAuth request.", false, 405);
  }

  if (!isConfigured(env)) {
    return htmlMessage(
      "SleepyServices",
      "SleepyServices authentication is not configured correctly.",
      false,
      500
    );
  }

  try {
    await ensureSchema(env);
  } catch (error) {
    console.error("Schema setup failed:", safeErrorMessage(error));
    return htmlMessage(
      "Kick connection failed",
      "SleepyServices could not prepare its connection store.",
      false,
      500
    );
  }

  const code = url.searchParams.get("code");
  const state = url.searchParams.get("state");
  const oauthError = url.searchParams.get("error");

  if (oauthError) {
    if (state) {
      try {
        await env.DB.prepare(
          `
          UPDATE oauth_sessions
          SET
            status = 'failed',
            error_code = 'authorization_denied',
            code_verifier = '',
            completed_at = ?
          WHERE state = ?
            AND status = 'pending'
          `
        )
          .bind(unixNow(), state)
          .run();
      } catch {
        // Deliberately do not expose database details.
      }
    }

    return htmlMessage(
      "Kick connection cancelled",
      "Kick was not connected through SleepyServices.",
      false,
      400
    );
  }

  if (!code || !state) {
    return htmlMessage(
      "SleepyServices",
      "The Kick authorization response was incomplete.",
      false,
      400
    );
  }

  const now = unixNow();
  let activeSessionId = "";

  try {
    const session = await env.DB.prepare(
      `
      SELECT
        session_id,
        connection_id,
        state,
        code_verifier,
        poll_token_hash,
        status,
        expires_at
      FROM oauth_sessions
      WHERE state = ?
      LIMIT 1
      `
    )
      .bind(state)
      .first();

    if (!session) {
      return htmlMessage(
        "Connection failed",
        "This authorization session is invalid or no longer exists.",
        false,
        400
      );
    }

    if (session.status !== "pending") {
      return htmlMessage(
        "Connection already processed",
        "This authorization attempt has already been used.",
        false,
        400
      );
    }

    if (Number(session.expires_at) < now) {
      await markSessionFailed(env, session.session_id, "session_expired");

      return htmlMessage(
        "Connection expired",
        "This Kick connection attempt expired. Return to the app and try again.",
        false,
        400
      );
    }

    const claim = await env.DB.prepare(
      `
      UPDATE oauth_sessions
      SET status = 'processing'
      WHERE session_id = ?
        AND status = 'pending'
        AND expires_at >= ?
      `
    )
      .bind(session.session_id, now)
      .run();

    if (!claim.success || Number(claim.meta?.changes || 0) !== 1) {
      return htmlMessage(
        "Connection already processed",
        "This authorization attempt is no longer available.",
        false,
        400
      );
    }

    activeSessionId = String(session.session_id);

    const tokenBody = new URLSearchParams();
    tokenBody.set("grant_type", "authorization_code");
    tokenBody.set("client_id", env.KICK_CLIENT_ID);
    tokenBody.set("client_secret", env.KICK_CLIENT_SECRET);
    tokenBody.set("redirect_uri", env.KICK_REDIRECT_URI);
    tokenBody.set("code_verifier", session.code_verifier);
    tokenBody.set("code", code);

    const tokenResponse = await fetch(KICK_TOKEN_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Accept: "application/json",
      },
      body: tokenBody.toString(),
    });

    if (!tokenResponse.ok) {
      console.error("Kick token exchange failed with HTTP", tokenResponse.status);
      await markSessionFailed(env, session.session_id, "token_exchange_failed");

      return htmlMessage(
        "Kick connection failed",
        "Kick could not complete the authorization. Return to the app and try again.",
        false,
        400
      );
    }

    const tokenData = await tokenResponse.json();

    if (!tokenData.access_token || !tokenData.refresh_token || !tokenData.expires_in) {
      await markSessionFailed(env, session.session_id, "invalid_token_response");

      return htmlMessage(
        "Kick connection failed",
        "Kick returned an incomplete authorization response.",
        false,
        500
      );
    }

    const userResponse = await fetch(KICK_USERS_URL, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${tokenData.access_token}`,
        Accept: "application/json",
      },
    });

    if (!userResponse.ok) {
      console.error("Kick user lookup failed with HTTP", userResponse.status);
      await markSessionFailed(env, session.session_id, "user_lookup_failed");

      return htmlMessage(
        "Kick connection failed",
        "SleepyServices could not identify the authorized Kick account.",
        false,
        500
      );
    }

    const userData = await userResponse.json();
    const kickUser =
      Array.isArray(userData.data) && userData.data.length > 0
        ? userData.data[0]
        : null;

    if (!kickUser || kickUser.user_id == null || !kickUser.name) {
      await markSessionFailed(env, session.session_id, "invalid_user_response");

      return htmlMessage(
        "Kick connection failed",
        "Kick returned incomplete account information.",
        false,
        500
      );
    }

    const expiresIn = Number(tokenData.expires_in);

    if (!Number.isFinite(expiresIn) || expiresIn <= 0) {
      await markSessionFailed(env, session.session_id, "invalid_expiration");

      return htmlMessage(
        "Kick connection failed",
        "Kick returned an invalid token expiration.",
        false,
        500
      );
    }

    const accessTokenEncrypted = await encryptSecret(
      tokenData.access_token,
      env.TOKEN_ENCRYPTION_KEY,
      session.connection_id
    );

    const refreshTokenEncrypted = await encryptSecret(
      tokenData.refresh_token,
      env.TOKEN_ENCRYPTION_KEY,
      session.connection_id
    );

    const tokenExpiresAt = now + Math.floor(expiresIn);
    const scopes = normalizeScopes(tokenData.scope, KICK_SCOPES.join(" "));
    const tokenType = String(tokenData.token_type || "Bearer");

    await env.DB.batch([
      env.DB.prepare(
        `
        INSERT INTO kick_connections (
          connection_id,
          kick_user_id,
          kick_username,
          access_token_enc,
          refresh_token_enc,
          token_type,
          token_expires_at,
          scopes,
          created_at,
          updated_at,
          last_refresh_at,
          revoked_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL)
        `
      ).bind(
        session.connection_id,
        String(kickUser.user_id),
        String(kickUser.name),
        accessTokenEncrypted,
        refreshTokenEncrypted,
        tokenType,
        tokenExpiresAt,
        scopes,
        now,
        now
      ),

      env.DB.prepare(
        `
        INSERT INTO connection_credentials (
          connection_id,
          token_hash,
          created_at,
          updated_at
        )
        VALUES (?, ?, ?, ?)

        ON CONFLICT(connection_id)
        DO UPDATE SET
          token_hash = excluded.token_hash,
          updated_at = excluded.updated_at
        `
      ).bind(session.connection_id, session.poll_token_hash, now, now),

      env.DB.prepare(
        `
        UPDATE oauth_sessions
        SET
          status = 'completed',
          code_verifier = '',
          error_code = NULL,
          completed_at = ?
        WHERE session_id = ?
        `
      ).bind(now, session.session_id),
    ]);

    activeSessionId = "";

    return htmlMessage(
      "Kick connected",
      `Kick account ${String(kickUser.name)} is now securely connected through SleepyServices.`,
      true,
      200
    );
  } catch (error) {
    console.error("OAuth callback failed:", safeErrorMessage(error));

    // If the callback failed after claiming the session, do not leave the
    // desktop stuck forever in the `processing` state. Persist a terminal
    // failure so the existing OAuth poller can surface the problem.
    if (activeSessionId) {
      try {
        await markSessionFailed(env, activeSessionId, "callback_processing_failed");
      } catch (markError) {
        console.error("OAuth failure-state update failed:", safeErrorMessage(markError));
      }
    }

    return htmlMessage(
      "Kick connection failed",
      "SleepyServices could not complete the connection. Return to the app and try again.",
      false,
      500
    );
  }
}

// ================================================================
// PERSISTENT CONNECTION STATUS
// ================================================================

async function handleConnectionStatus(request, env) {
  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!isConfigured(env)) {
    return jsonError("server_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const auth = await authenticateConnectionRequest(request, env);
    if (auth.response) {
      return auth.response;
    }

    let connection = auth.connection;

    if (connection.revoked_at != null) {
      return Response.json(
        {
          status: "disconnected",
          connection: publicConnection(connection),
        },
        { headers: noStoreHeaders() }
      );
    }

    const freshness = await ensureFreshKickConnection(env, connection, false);

    if (freshness.kind === "refreshing") {
      return Response.json(
        {
          status: "refreshing",
          connection: publicConnection(freshness.connection),
        },
        { status: 202, headers: noStoreHeaders() }
      );
    }

    if (freshness.kind === "temporary_failure") {
      return Response.json(
        {
          status: "degraded",
          error: "token_refresh_temporarily_failed",
          connection: publicConnection(freshness.connection),
        },
        { status: 503, headers: noStoreHeaders() }
      );
    }

    if (freshness.kind === "reconnect_required") {
      return Response.json(
        {
          status: "reconnect_required",
          error: "token_refresh_rejected",
          connection: publicConnection(freshness.connection),
        },
        { status: 401, headers: noStoreHeaders() }
      );
    }

    connection = freshness.connection;

    return Response.json(
      {
        status: "connected",
        refreshed: freshness.refreshed,
        connection: publicConnection(connection),
      },
      { headers: noStoreHeaders() }
    );
  } catch (error) {
    console.error("Persistent status failed:", safeErrorMessage(error));
    return jsonError("connection_status_failed", 500);
  }
}

// ================================================================
// FORCED TOKEN REFRESH
// ================================================================

async function handleConnectionRefresh(request, env) {
  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!isConfigured(env)) {
    return jsonError("server_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const auth = await authenticateConnectionRequest(request, env);
    if (auth.response) {
      return auth.response;
    }

    const connection = auth.connection;

    if (connection.revoked_at != null) {
      return Response.json(
        {
          status: "disconnected",
          connection: publicConnection(connection),
        },
        { headers: noStoreHeaders() }
      );
    }

    const result = await ensureFreshKickConnection(env, connection, true);

    if (result.kind === "refreshing") {
      return Response.json(
        {
          status: "refreshing",
          connection: publicConnection(result.connection),
        },
        { status: 202, headers: noStoreHeaders() }
      );
    }

    if (result.kind === "temporary_failure") {
      return Response.json(
        {
          status: "degraded",
          error: "token_refresh_temporarily_failed",
          connection: publicConnection(result.connection),
        },
        { status: 503, headers: noStoreHeaders() }
      );
    }

    if (result.kind === "reconnect_required") {
      return Response.json(
        {
          status: "reconnect_required",
          error: "token_refresh_rejected",
          connection: publicConnection(result.connection),
        },
        { status: 401, headers: noStoreHeaders() }
      );
    }

    return Response.json(
      {
        status: "connected",
        refreshed: result.refreshed,
        connection: publicConnection(result.connection),
      },
      { headers: noStoreHeaders() }
    );
  } catch (error) {
    console.error("Forced refresh failed:", safeErrorMessage(error));
    return jsonError("token_refresh_failed", 500);
  }
}


// ================================================================
// EVENT SUBSCRIPTION STATUS
// ================================================================

async function handleEventSubscriptionsStatus(request, env) {
  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!isConfigured(env)) {
    return jsonError("server_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const auth = await authenticateConnectionRequest(request, env);
    if (auth.response) {
      return auth.response;
    }

    if (auth.connection.revoked_at != null) {
      return Response.json(
        { status: "disconnected" },
        { headers: noStoreHeaders() }
      );
    }

    const tokenResult = await getUsableKickAccessToken(env, auth.connection);
    if (tokenResult.response) {
      return tokenResult.response;
    }

    const remote = await fetchKickEventSubscriptions(
      tokenResult.accessToken,
      tokenResult.connection.kick_user_id
    );

    if (!remote.ok) {
      return kickApiFailure(
        "event_subscription_status_failed",
        remote.status,
        remote.message
      );
    }

    const subscriptions = normalizeKickSubscriptions(remote.data);

    await replaceLocalSubscriptionMappings(
      env,
      tokenResult.connection,
      subscriptions
    );

    const summary = summarizeRequiredSubscriptions(subscriptions);

    return Response.json(
      {
        status: "ok",
        all_required_subscribed: summary.missing.length === 0,
        refreshed: tokenResult.refreshed,
        required_events: SLEEPYSOURCE_BASE_EVENTS,
        missing_events: summary.missing,
        subscriptions: subscriptions.map(publicSubscription),
      },
      { headers: noStoreHeaders() }
    );
  } catch (error) {
    console.error(
      "Event subscription status failed:",
      safeErrorMessage(error)
    );

    return jsonError("event_subscription_status_failed", 500);
  }
}

// ================================================================
// EVENT SUBSCRIPTION SYNC
// ================================================================

async function handleEventSubscriptionsSync(request, env) {
  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!isConfigured(env)) {
    return jsonError("server_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const auth = await authenticateConnectionRequest(request, env);
    if (auth.response) {
      return auth.response;
    }

    if (auth.connection.revoked_at != null) {
      return Response.json(
        { status: "disconnected" },
        { headers: noStoreHeaders() }
      );
    }

    const tokenResult = await getUsableKickAccessToken(env, auth.connection);
    if (tokenResult.response) {
      return tokenResult.response;
    }

    const beforeRemote = await fetchKickEventSubscriptions(
      tokenResult.accessToken,
      tokenResult.connection.kick_user_id
    );

    if (!beforeRemote.ok) {
      return kickApiFailure(
        "event_subscription_list_failed",
        beforeRemote.status,
        beforeRemote.message
      );
    }

    const before = normalizeKickSubscriptions(beforeRemote.data);
    const requiredKeys = new Set(
      SLEEPYSOURCE_BASE_EVENTS.map(
        (event) => `${event.name}@${event.version}`
      )
    );
    const existingRequired = before.filter(
      (subscription) =>
        requiredKeys.has(`${subscription.event}@${subscription.version}`)
    );
    const attempts = [];
    const removedSubscriptionIds = existingRequired.map(
      (subscription) => subscription.id
    );

    // A manual/automatic SleepySource sync is also a repair operation.
    // Recreate the managed subscriptions so Kick rebinds them to the
    // developer application's current webhook URL. This is important after
    // a webhook-domain migration or when Kick has silently stopped delivering
    // an otherwise healthy-looking subscription.
    if (removedSubscriptionIds.length > 0) {
      const deleteResult = await deleteKickEventSubscriptions(
        tokenResult.accessToken,
        removedSubscriptionIds
      );

      if (!deleteResult.ok) {
        return kickApiFailure(
          "event_subscription_delete_failed",
          deleteResult.status,
          deleteResult.message
        );
      }
    }

    // Subscribe one event at a time. If Kick rejects one event type,
    // the other required SleepySource events can still be activated.
    for (const event of SLEEPYSOURCE_BASE_EVENTS) {
      const createResult = await createKickEventSubscription(
        tokenResult.accessToken,
        event
      );

      attempts.push({
        name: event.name,
        version: event.version,
        http_status: createResult.status,
        accepted: createResult.ok,
        result: createResult.data,
        message: createResult.message || null,
      });
    }

    const afterRemote = await fetchKickEventSubscriptions(
      tokenResult.accessToken,
      tokenResult.connection.kick_user_id
    );

    if (!afterRemote.ok) {
      return kickApiFailure(
        "event_subscription_verify_failed",
        afterRemote.status,
        afterRemote.message
      );
    }

    const after = normalizeKickSubscriptions(afterRemote.data);

    await replaceLocalSubscriptionMappings(
      env,
      tokenResult.connection,
      after
    );

    const afterSummary = summarizeRequiredSubscriptions(after);
    const complete = afterSummary.missing.length === 0;

    return Response.json(
      {
        status: complete ? "subscribed" : "partial",
        all_required_subscribed: complete,
        refreshed: tokenResult.refreshed,
        subscriptions_recreated: true,
        removed_subscription_ids: removedSubscriptionIds,
        attempted: attempts,
        missing_events: afterSummary.missing,
        subscriptions: after.map(publicSubscription),
      },
      {
        status: complete ? 200 : 207,
        headers: noStoreHeaders(),
      }
    );
  } catch (error) {
    console.error(
      "Event subscription sync failed:",
      safeErrorMessage(error)
    );

    return jsonError("event_subscription_sync_failed", 500);
  }
}

// ================================================================
// AUTHENTICATED CHANNEL + CATEGORY PROXY
// The desktop never receives Kick access or refresh tokens.
// ================================================================

async function handleChannelMetadata(request, env) {
  if (request.method !== "POST") return jsonError("method_not_allowed", 405);
  if (!isConfigured(env)) return jsonError("server_not_configured", 500);

  try {
    await ensureSchema(env);
    const auth = await authenticateConnectionRequest(request, env);
    if (auth.response) return auth.response;
    if (auth.connection.revoked_at != null) {
      return Response.json({ status: "disconnected" }, { status: 401, headers: noStoreHeaders() });
    }

    const tokenResult = await getUsableKickAccessToken(env, auth.connection);
    if (tokenResult.response) return tokenResult.response;
    const meta = await readAuthorizedChannelMetadata(tokenResult.accessToken, tokenResult.connection);
    if (meta.response) return meta.response;
    return Response.json(channelMetadataResponse(meta.value), { headers: noStoreHeaders() });
  } catch (error) {
    console.error("Channel metadata proxy failed:", safeErrorMessage(error));
    return jsonError("channel_metadata_failed", 500);
  }
}

async function handleCategorySearch(request, env) {
  if (request.method !== "POST") return jsonError("method_not_allowed", 405);
  if (!isConfigured(env)) return jsonError("server_not_configured", 500);

  try {
    await ensureSchema(env);
    const body = await readJson(request);
    if (!body) return jsonError("invalid_json", 400);
    const auth = await authenticateConnectionBody(body, env);
    if (auth.response) return auth.response;
    if (auth.connection.revoked_at != null) {
      return Response.json({ status: "disconnected", categories: [] }, { status: 401, headers: noStoreHeaders() });
    }

    const query = String(body.query || "").trim().slice(0, 120);
    if (!query) return Response.json({ status: "ok", categories: [] }, { headers: noStoreHeaders() });
    const tokenResult = await getUsableKickAccessToken(env, auth.connection);
    if (tokenResult.response) return tokenResult.response;
    const result = await searchKickCategories(tokenResult.accessToken, query);
    if (!result.ok) return kickApiFailure("category_search_failed", result.status, result.message);
    return Response.json({ status: "ok", categories: result.categories }, { headers: noStoreHeaders() });
  } catch (error) {
    console.error("Category search proxy failed:", safeErrorMessage(error));
    return jsonError("category_search_failed", 500);
  }
}

async function handleChannelUpdate(request, env) {
  if (request.method !== "POST") return jsonError("method_not_allowed", 405);
  if (!isConfigured(env)) return jsonError("server_not_configured", 500);

  try {
    await ensureSchema(env);
    const body = await readJson(request);
    if (!body) return jsonError("invalid_json", 400);
    const auth = await authenticateConnectionBody(body, env);
    if (auth.response) return auth.response;
    if (auth.connection.revoked_at != null) {
      return Response.json({ status: "disconnected" }, { status: 401, headers: noStoreHeaders() });
    }

    const title = String(body.title || "").trim().slice(0, 140);
    if (!title) return jsonError("stream_title_required", 400);
    let categoryId = Number(body.category_id || 0);
    let categoryName = String(body.category_name || "").trim().slice(0, 120);

    const tokenResult = await getUsableKickAccessToken(env, auth.connection);
    if (tokenResult.response) return tokenResult.response;

    if (!(categoryId > 0) && categoryName) {
      const categoryResult = await searchKickCategories(tokenResult.accessToken, categoryName);
      if (!categoryResult.ok) return kickApiFailure("category_search_failed", categoryResult.status, categoryResult.message);
      const exact = categoryResult.categories.find((item) => item.name.toLowerCase() === categoryName.toLowerCase());
      const selected = exact || categoryResult.categories[0];
      if (!selected) return jsonError("category_not_found", 404);
      categoryId = selected.id;
      categoryName = selected.name;
    }

    const patch = { stream_title: title };
    if (categoryId > 0) patch.category_id = categoryId;
    const remote = await kickJsonRequest(KICK_CHANNELS_URL, {
      method: "PATCH",
      headers: {
        Authorization: `Bearer ${tokenResult.accessToken}`,
        Accept: "application/json",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(patch),
    });
    if (!remote.ok) return kickApiFailure("channel_update_failed", remote.status, remote.message);

    let meta = null;
    for (let attempt = 0; attempt < 4; attempt += 1) {
      if (attempt > 0) await new Promise((resolve) => setTimeout(resolve, attempt * 350));
      const readback = await readAuthorizedChannelMetadata(tokenResult.accessToken, tokenResult.connection);
      if (!readback.response) {
        meta = readback.value;
        if (!meta.is_live || (meta.title.toLowerCase() === title.toLowerCase() && (!(categoryId > 0) || meta.category_id === categoryId))) break;
      }
    }

    if (meta?.is_live && (meta.title.toLowerCase() !== title.toLowerCase() || (categoryId > 0 && meta.category_id !== categoryId))) {
      return Response.json({ status: "verification_failed", error: "kick_readback_mismatch", ...channelMetadataResponse(meta) }, { status: 502, headers: noStoreHeaders() });
    }

    const output = meta || {
      broadcaster_user_id: Number(tokenResult.connection.kick_user_id || 0),
      channel: String(tokenResult.connection.kick_username || ""),
      title,
      category_id: categoryId > 0 ? categoryId : 0,
      category_name: categoryName,
      is_live: false,
    };
    return Response.json({
      ok: true,
      verified: Boolean(output.is_live),
      verification_status: output.is_live ? "verified" : "accepted_offline",
      ...channelMetadataResponse(output),
      message: output.is_live
        ? "Kick stream settings updated and verified on the active livestream"
        : "Kick accepted the stream update. It will be verified when the channel is live.",
    }, { headers: noStoreHeaders() });
  } catch (error) {
    console.error("Channel update proxy failed:", safeErrorMessage(error));
    return jsonError("channel_update_failed", 500);
  }
}

async function readAuthorizedChannelMetadata(accessToken, connection) {
  const channelResponse = await kickJsonRequest(KICK_CHANNELS_URL, {
    method: "GET",
    headers: { Authorization: `Bearer ${accessToken}`, Accept: "application/json" },
  });
  if (!channelResponse.ok) {
    return { response: kickApiFailure("channel_metadata_failed", channelResponse.status, channelResponse.message) };
  }
  const channels = Array.isArray(channelResponse.data) ? channelResponse.data : [];
  if (channels.length === 0) return { response: jsonError("channel_metadata_missing", 404) };
  // GET /public/v1/channels already returns the authenticated channel's
  // current stream object, title and category. Avoid the deprecated V1
  // livestream listing endpoint entirely.
  const value = normalizeChannelMetadata(channels[0], connection);
  return { value };
}

function normalizeChannelMetadata(item, connection, fallback = null) {
  const category = item?.category && typeof item.category === "object" ? item.category : {};
  return {
    broadcaster_user_id: Number(item?.broadcaster_user_id || fallback?.broadcaster_user_id || connection?.kick_user_id || 0),
    channel: String(item?.slug || fallback?.channel || connection?.kick_username || "").trim().toLowerCase(),
    title: String(item?.stream_title || item?.title || fallback?.title || "").trim(),
    category_id: Number(category?.id || item?.category_id || fallback?.category_id || 0),
    category_name: String(category?.name || item?.category_name || fallback?.category_name || "").trim(),
    is_live: Boolean(item?.is_live || item?.stream?.is_live || fallback?.is_live || false),
  };
}

function channelMetadataResponse(meta) {
  return {
    connected: true,
    auth_ready: true,
    channel: meta.channel,
    broadcaster_user_id: meta.broadcaster_user_id,
    title: meta.title,
    category_id: meta.category_id,
    category_name: meta.category_name,
    is_live: Boolean(meta.is_live),
    metadata_readback_available: Boolean(meta.is_live || meta.title || meta.category_id || meta.category_name),
    update_supported: true,
    stream_authorized: true,
    authorized_channel: meta.channel,
    authorized_broadcaster_user_id: meta.broadcaster_user_id,
    authorized_channel_matches: true,
    connected_channel: meta.channel,
  };
}

async function searchKickCategories(accessToken, query) {
  const url = new URL(KICK_CATEGORIES_URL);
  url.searchParams.set("limit", "20");
  url.searchParams.set("name", query);
  const remote = await kickJsonRequest(url.toString(), {
    method: "GET",
    headers: { Authorization: `Bearer ${accessToken}`, Accept: "application/json" },
  });
  if (!remote.ok) return { ok: false, status: remote.status, message: remote.message, categories: [] };
  const seen = new Set();
  const categories = [];
  for (const item of Array.isArray(remote.data) ? remote.data : []) {
    const id = Number(item?.id || 0);
    const name = String(item?.name || "").trim();
    if (id > 0 && name && !seen.has(id)) {
      seen.add(id);
      categories.push({ id, name });
    }
  }
  return { ok: true, status: remote.status, categories };
}

// ================================================================
// EVENT SUBSCRIPTION HELPERS
// ================================================================

async function getUsableKickAccessToken(env, connection) {
  const freshness = await ensureFreshKickConnection(
    env,
    connection,
    false
  );

  if (freshness.kind === "refreshing") {
    return {
      response: Response.json(
        {
          status: "refreshing",
          error: "token_refresh_in_progress",
        },
        {
          status: 202,
          headers: noStoreHeaders(),
        }
      ),
    };
  }

  if (freshness.kind === "temporary_failure") {
    return {
      response: Response.json(
        {
          status: "degraded",
          error: "token_refresh_temporarily_failed",
        },
        {
          status: 503,
          headers: noStoreHeaders(),
        }
      ),
    };
  }

  if (freshness.kind === "reconnect_required") {
    return {
      response: Response.json(
        {
          status: "reconnect_required",
          error: "token_refresh_rejected",
        },
        {
          status: 401,
          headers: noStoreHeaders(),
        }
      ),
    };
  }

  const activeConnection = freshness.connection;

  try {
    const accessToken = await decryptSecret(
      activeConnection.access_token_enc,
      env.TOKEN_ENCRYPTION_KEY,
      activeConnection.connection_id
    );

    return {
      accessToken,
      connection: activeConnection,
      refreshed: freshness.refreshed,
    };
  } catch (error) {
    console.error(
      "Access token decrypt failed:",
      safeErrorMessage(error)
    );

    return {
      response: jsonError("access_token_decrypt_failed", 500),
    };
  }
}

async function fetchKickEventSubscriptions(accessToken, broadcasterUserId) {
  const url = new URL(KICK_EVENT_SUBSCRIPTIONS_URL);

  if (broadcasterUserId) {
    url.searchParams.set(
      "broadcaster_user_id",
      String(broadcasterUserId)
    );
  }

  return kickJsonRequest(url.toString(), {
    method: "GET",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: "application/json",
    },
  });
}

async function deleteKickEventSubscriptions(accessToken, subscriptionIds) {
  const ids = [...new Set(
    (Array.isArray(subscriptionIds) ? subscriptionIds : [])
      .map((value) => String(value || "").trim())
      .filter(Boolean)
  )];

  if (ids.length === 0) {
    return { ok: true, status: 204, data: null, message: null };
  }

  const url = new URL(KICK_EVENT_SUBSCRIPTIONS_URL);
  for (const id of ids) {
    url.searchParams.append("id", id);
  }

  return kickJsonRequest(url.toString(), {
    method: "DELETE",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: "application/json",
    },
  });
}

async function createKickEventSubscription(accessToken, event) {
  return kickJsonRequest(KICK_EVENT_SUBSCRIPTIONS_URL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: "application/json",
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      events: [
        {
          name: event.name,
          version: event.version,
        },
      ],
      method: "webhook",
    }),
  });
}

async function kickJsonRequest(url, options) {
  let response;

  try {
    response = await fetch(url, options);
  } catch (error) {
    console.error(
      "Kick API network failure:",
      safeErrorMessage(error)
    );

    return {
      ok: false,
      status: 0,
      data: null,
      message: "network_failure",
    };
  }

  let payload = null;

  try {
    payload = await response.json();
  } catch {
    payload = null;
  }

  return {
    ok: response.ok,
    status: response.status,
    data: payload?.data ?? null,
    message:
      typeof payload?.message === "string"
        ? payload.message
        : null,
  };
}

function normalizeKickSubscriptions(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((item) => ({
      id: String(item?.id || item?.subscription_id || "").trim(),
      app_id: String(item?.app_id || "").trim(),
      broadcaster_user_id:
        item?.broadcaster_user_id == null
          ? ""
          : String(item.broadcaster_user_id),
      event: String(item?.event || item?.name || "").trim(),
      version: Number(item?.version || 0),
      method: String(item?.method || "webhook").trim(),
      created_at:
        item?.created_at == null ? null : String(item.created_at),
      updated_at:
        item?.updated_at == null ? null : String(item.updated_at),
    }))
    .filter(
      (item) =>
        item.id &&
        item.event &&
        Number.isFinite(item.version) &&
        item.version > 0
    );
}

function summarizeRequiredSubscriptions(subscriptions) {
  const activeKeys = new Set(
    subscriptions.map(
      (item) => `${item.event}@${item.version}`
    )
  );

  const missing = SLEEPYSOURCE_BASE_EVENTS.filter(
    (event) => !activeKeys.has(`${event.name}@${event.version}`)
  );

  return { missing };
}

function publicSubscription(subscription) {
  return {
    subscription_id: subscription.id,
    event: subscription.event,
    version: subscription.version,
    method: subscription.method,
    broadcaster_user_id: subscription.broadcaster_user_id,
  };
}

async function replaceLocalSubscriptionMappings(
  env,
  connection,
  subscriptions
) {
  const now = unixNow();

  const statements = [
    env.DB.prepare(
      `
      DELETE FROM kick_event_subscriptions
      WHERE connection_id = ?
      `
    ).bind(connection.connection_id),
  ];

  for (const subscription of subscriptions) {
    statements.push(
      env.DB.prepare(
        `
        INSERT INTO kick_event_subscriptions (
          subscription_id,
          connection_id,
          broadcaster_user_id,
          event_type,
          event_version,
          method,
          remote_created_at,
          remote_updated_at,
          synced_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)

        ON CONFLICT(subscription_id)
        DO UPDATE SET
          connection_id = excluded.connection_id,
          broadcaster_user_id = excluded.broadcaster_user_id,
          event_type = excluded.event_type,
          event_version = excluded.event_version,
          method = excluded.method,
          remote_created_at = excluded.remote_created_at,
          remote_updated_at = excluded.remote_updated_at,
          synced_at = excluded.synced_at
        `
      ).bind(
        subscription.id,
        connection.connection_id,
        subscription.broadcaster_user_id || String(connection.kick_user_id),
        subscription.event,
        subscription.version,
        subscription.method || "webhook",
        subscription.created_at,
        subscription.updated_at,
        now
      )
    );
  }

  await env.DB.batch(statements);
}

function kickApiFailure(code, upstreamStatus, message) {
  return Response.json(
    {
      status: "error",
      error: code,
      kick_http_status: upstreamStatus,
      kick_message: message || null,
    },
    {
      status: 502,
      headers: noStoreHeaders(),
    }
  );
}

// ================================================================
// DISCONNECT + KICK TOKEN REVOCATION
// ================================================================

async function handleConnectionDisconnect(request, env) {
  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!isConfigured(env)) {
    return jsonError("server_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const auth = await authenticateConnectionRequest(request, env);
    if (auth.response) {
      return auth.response;
    }

    const connection = auth.connection;

    // Idempotent: an already-disconnected connection stays disconnected.
    if (connection.revoked_at != null) {
      return Response.json(
        {
          status: "disconnected",
          already_disconnected: true,
          connection: publicConnection(connection),
        },
        { headers: noStoreHeaders() }
      );
    }

    let accessToken;
    let refreshToken;

    try {
      accessToken = await decryptSecret(
        connection.access_token_enc,
        env.TOKEN_ENCRYPTION_KEY,
        connection.connection_id
      );

      refreshToken = await decryptSecret(
        connection.refresh_token_enc,
        env.TOKEN_ENCRYPTION_KEY,
        connection.connection_id
      );
    } catch (error) {
      console.error("Disconnect decrypt failed:", safeErrorMessage(error));
      return jsonError("disconnect_decrypt_failed", 500);
    }

    // Revoke the refresh token first. This is the critical long-lived
    // credential because it can mint replacement access tokens.
    const refreshRevoke = await revokeKickToken(refreshToken, "refresh_token");

    // Also make a best-effort attempt to revoke the current access token.
    const accessRevoke = await revokeKickToken(accessToken, "access_token");

    if (!refreshRevoke.ok) {
      console.error(
        "Kick refresh token revoke failed with HTTP",
        refreshRevoke.status
      );

      // Do NOT mark the connection locally disconnected if Kick did not
      // confirm revocation of the refresh token. This lets the user retry.
      return Response.json(
        {
          status: "disconnect_failed",
          error: "kick_refresh_token_revoke_failed",
          remote: {
            refresh_token_revoke_confirmed: false,
            access_token_revoke_confirmed: accessRevoke.ok,
          },
        },
        { status: 502, headers: noStoreHeaders() }
      );
    }

    const now = unixNow();

    // Kick confirmed the refresh token was revoked. Disable the local
    // connection and wipe both encrypted Kick tokens from D1.
    await env.DB.prepare(
      `
      UPDATE kick_connections
      SET
        access_token_enc = '',
        refresh_token_enc = '',
        token_expires_at = 0,
        updated_at = ?,
        revoked_at = ?
      WHERE connection_id = ?
        AND revoked_at IS NULL
      `
    )
      .bind(now, now, connection.connection_id)
      .run();

    await env.DB.prepare(
      `
      DELETE FROM kick_event_subscriptions
      WHERE connection_id = ?
      `
    )
      .bind(connection.connection_id)
      .run();

    if (env.REALTIME) {
      try {
        const realtimeStub = env.REALTIME.getByName(connection.connection_id);
        await realtimeStub.disconnectAll("Kick connection revoked");
      } catch (error) {
        console.error(
          "Realtime disconnect cleanup failed:",
          safeErrorMessage(error)
        );
      }
    }

    const disconnected = await loadConnection(env, connection.connection_id);

    return Response.json(
      {
        status: "disconnected",
        already_disconnected: false,
        remote: {
          refresh_token_revoke_confirmed: true,
          access_token_revoke_confirmed: accessRevoke.ok,
        },
        connection: publicConnection(disconnected || {
          ...connection,
          token_expires_at: 0,
          updated_at: now,
          revoked_at: now,
        }),
      },
      { headers: noStoreHeaders() }
    );
  } catch (error) {
    console.error("Disconnect failed:", safeErrorMessage(error));
    return jsonError("disconnect_failed", 500);
  }
}

// ================================================================
// KICK REVOCATION
// ================================================================

async function revokeKickToken(token, tokenHintType) {
  const revokeUrl = new URL(KICK_REVOKE_URL);
  revokeUrl.searchParams.set("token", token);
  revokeUrl.searchParams.set("token_type_hint", tokenHintType);

  try {
    const response = await fetch(revokeUrl.toString(), {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Accept: "text/plain, application/json",
      },
      body: "",
    });

    return {
      ok: response.ok,
      status: response.status,
    };
  } catch (error) {
    console.error("Kick revoke network failure:", safeErrorMessage(error));

    return {
      ok: false,
      status: 0,
    };
  }
}

// ================================================================
// RELIABLE DESKTOP EVENT DELIVERY
// ================================================================

async function handleEventDeliveryPoll(request, env) {
  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!isConfigured(env)) {
    return jsonError("server_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const body = await readJson(request);

    if (!body) {
      return jsonError("invalid_json", 400);
    }

    const auth = await authenticateConnectionBody(body, env);

    if (auth.response) {
      return auth.response;
    }

    const connection = auth.connection;

    if (connection.revoked_at != null) {
      return Response.json(
        {
          status: "disconnected",
          events: [],
        },
        {
          headers: noStoreHeaders(),
        }
      );
    }

    const requestedLimit = Number(body.limit);
    const limit = Number.isFinite(requestedLimit)
      ? Math.min(
          EVENT_DELIVERY_MAX_LIMIT,
          Math.max(1, Math.floor(requestedLimit))
        )
      : EVENT_DELIVERY_DEFAULT_LIMIT;

    const now = unixNow();

    // Backfill any verified webhooks that arrived before the delivery
    // queue row could be created. This makes deployment/restart timing safe.
    await repairEventDeliveriesForConnection(
      env,
      connection.connection_id,
      now
    );

    const candidatesResult = await env.DB.prepare(
      `
      SELECT message_id
      FROM desktop_event_deliveries
      WHERE connection_id = ?
        AND acked_at IS NULL
        AND (
          status = 'pending'
          OR (
            status = 'leased'
            AND lease_expires_at < ?
          )
        )
      ORDER BY created_at ASC
      LIMIT ?
      `
    )
      .bind(connection.connection_id, now, limit)
      .all();

    const candidates = Array.isArray(candidatesResult.results)
      ? candidatesResult.results
      : [];

    if (candidates.length === 0) {
      return Response.json(
        {
          status: "empty",
          events: [],
          retry_after_ms: 1000,
        },
        {
          headers: noStoreHeaders(),
        }
      );
    }

    const leaseId = randomBase64Url(24);
    const leaseExpiresAt = now + EVENT_DELIVERY_LEASE_SECONDS;

    const claimStatements = candidates.map((row) =>
      env.DB.prepare(
        `
        UPDATE desktop_event_deliveries
        SET
          status = 'leased',
          lease_id = ?,
          lease_expires_at = ?,
          attempt_count = attempt_count + 1,
          last_attempt_at = ?,
          updated_at = ?
        WHERE message_id = ?
          AND connection_id = ?
          AND acked_at IS NULL
          AND (
            status = 'pending'
            OR (
              status = 'leased'
              AND lease_expires_at < ?
            )
          )
        `
      ).bind(
        leaseId,
        leaseExpiresAt,
        now,
        now,
        String(row.message_id),
        connection.connection_id,
        now
      )
    );

    if (claimStatements.length > 0) {
      await env.DB.batch(claimStatements);
    }

    const claimedResult = await env.DB.prepare(
      `
      SELECT
        d.message_id,
        d.attempt_count,
        d.lease_expires_at,
        e.event_type,
        e.event_version,
        e.event_timestamp,
        e.payload_json,
        e.received_at
      FROM desktop_event_deliveries d
      INNER JOIN kick_webhook_events e
        ON e.message_id = d.message_id
      WHERE d.connection_id = ?
        AND d.lease_id = ?
        AND d.acked_at IS NULL
      ORDER BY d.created_at ASC
      `
    )
      .bind(connection.connection_id, leaseId)
      .all();

    const rows = Array.isArray(claimedResult.results)
      ? claimedResult.results
      : [];

    const events = rows.map((row) => {
      let payload = null;

      try {
        payload = JSON.parse(String(row.payload_json));
      } catch {
        payload = null;
      }

      return {
        message_id: String(row.message_id),
        event_type: String(row.event_type),
        event_version: Number(row.event_version),
        event_timestamp: String(row.event_timestamp),
        received_at: Number(row.received_at),
        attempt_count: Number(row.attempt_count),
        lease_expires_at: Number(row.lease_expires_at),
        payload,
      };
    });

    return Response.json(
      {
        status: events.length > 0 ? "events" : "empty",
        events,
        lease_seconds: EVENT_DELIVERY_LEASE_SECONDS,
        retry_after_ms: events.length > 0 ? 0 : 1000,
      },
      {
        headers: noStoreHeaders(),
      }
    );
  } catch (error) {
    console.error(
      "Event delivery poll failed:",
      safeErrorMessage(error)
    );

    return jsonError("event_delivery_poll_failed", 500);
  }
}

async function handleEventDeliveryAck(request, env) {
  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!isConfigured(env)) {
    return jsonError("server_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const body = await readJson(request);

    if (!body) {
      return jsonError("invalid_json", 400);
    }

    const auth = await authenticateConnectionBody(body, env);

    if (auth.response) {
      return auth.response;
    }

    const connection = auth.connection;

    if (connection.revoked_at != null) {
      return Response.json(
        {
          status: "disconnected",
          newly_acknowledged: 0,
        },
        {
          headers: noStoreHeaders(),
        }
      );
    }

    const rawMessageIds = Array.isArray(body.message_ids)
      ? body.message_ids
      : body.message_id
        ? [body.message_id]
        : [];

    const messageIds = [
      ...new Set(
        rawMessageIds
          .map((value) => cleanCredential(value, 128))
          .filter(Boolean)
      ),
    ].slice(0, EVENT_DELIVERY_MAX_LIMIT);

    if (messageIds.length === 0) {
      return jsonError("missing_message_ids", 400);
    }

    const now = unixNow();

    const ackStatements = messageIds.map((messageId) =>
      env.DB.prepare(
        `
        UPDATE desktop_event_deliveries
        SET
          status = 'acked',
          acked_at = ?,
          lease_id = NULL,
          lease_expires_at = NULL,
          updated_at = ?
        WHERE message_id = ?
          AND connection_id = ?
          AND acked_at IS NULL
        `
      ).bind(
        now,
        now,
        messageId,
        connection.connection_id
      )
    );

    const ackResults = await env.DB.batch(ackStatements);

    const newlyAcknowledged = ackResults.reduce(
      (total, result) => total + Number(result.meta?.changes || 0),
      0
    );

    // processed_at means the desktop application has acknowledged the event.
    const processedStatements = messageIds.map((messageId) =>
      env.DB.prepare(
        `
        UPDATE kick_webhook_events
        SET processed_at = COALESCE(processed_at, ?)
        WHERE message_id = ?
          AND EXISTS (
            SELECT 1
            FROM desktop_event_deliveries
            WHERE message_id = ?
              AND connection_id = ?
              AND acked_at IS NOT NULL
          )
        `
      ).bind(
        now,
        messageId,
        messageId,
        connection.connection_id
      )
    );

    await env.DB.batch(processedStatements);

    return Response.json(
      {
        status: "ok",
        requested: messageIds.length,
        newly_acknowledged: newlyAcknowledged,
      },
      {
        headers: noStoreHeaders(),
      }
    );
  } catch (error) {
    console.error(
      "Event delivery acknowledgement failed:",
      safeErrorMessage(error)
    );

    return jsonError("event_delivery_ack_failed", 500);
  }
}

async function repairEventDeliveriesForConnection(
  env,
  connectionId,
  now
) {
  await env.DB.prepare(
    `
    INSERT OR IGNORE INTO desktop_event_deliveries (
      message_id,
      connection_id,
      status,
      lease_id,
      lease_expires_at,
      attempt_count,
      last_attempt_at,
      created_at,
      updated_at,
      acked_at
    )
    SELECT
      e.message_id,
      s.connection_id,
      'pending',
      NULL,
      NULL,
      0,
      NULL,
      e.received_at,
      ?,
      NULL
    FROM kick_webhook_events e
    INNER JOIN kick_event_subscriptions s
      ON s.subscription_id = e.subscription_id
    WHERE s.connection_id = ?
    `
  )
    .bind(now, connectionId)
    .run();
}

// ================================================================
// REAL-TIME WEBSOCKET DELIVERY
// ================================================================

async function handleRealtimeConnect(request, env) {
  if (request.method !== "GET") {
    return jsonError("method_not_allowed", 405);
  }

  if (!env.DB || !env.REALTIME) {
    return jsonError("realtime_not_configured", 500);
  }

  const upgrade = String(request.headers.get("Upgrade") || "").toLowerCase();

  if (upgrade !== "websocket") {
    return Response.json(
      {
        status: "upgrade_required",
        endpoint: REALTIME_WEBSOCKET_PATH,
        protocol: "websocket",
      },
      {
        status: 426,
        headers: {
          ...noStoreHeaders(),
          Upgrade: "websocket",
        },
      }
    );
  }

  try {
    await ensureSchema(env);

    const auth = await authenticateConnectionHeaders(request, env);

    if (auth.response) {
      return auth.response;
    }

    if (auth.connection.revoked_at != null) {
      return Response.json(
        { status: "disconnected" },
        { status: 401, headers: noStoreHeaders() }
      );
    }

    const stub = env.REALTIME.getByName(auth.connection.connection_id);

    // The connection credential has already been verified by the Worker.
    // Forwarding through the Durable Object binding keeps the Durable Object
    // private; it is never exposed directly to the Internet.
    return await stub.fetch(request);
  } catch (error) {
    console.error("Realtime connect failed:", safeErrorMessage(error));
    return jsonError("realtime_connect_failed", 500);
  }
}

async function handleRealtimeStatus(request, env) {
  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!env.DB || !env.REALTIME) {
    return jsonError("realtime_not_configured", 500);
  }

  try {
    await ensureSchema(env);

    const auth = await authenticateConnectionRequest(request, env);

    if (auth.response) {
      return auth.response;
    }

    if (auth.connection.revoked_at != null) {
      return Response.json(
        {
          status: "disconnected",
          connected_clients: 0,
        },
        { headers: noStoreHeaders() }
      );
    }

    const stub = env.REALTIME.getByName(auth.connection.connection_id);
    const connectedClients = await stub.getConnectionCount();

    return Response.json(
      {
        status: "ok",
        realtime: connectedClients > 0 ? "connected" : "idle",
        connected_clients: Number(connectedClients || 0),
        fallback_queue: true,
      },
      { headers: noStoreHeaders() }
    );
  } catch (error) {
    console.error("Realtime status failed:", safeErrorMessage(error));
    return jsonError("realtime_status_failed", 500);
  }
}

async function authenticateConnectionHeaders(request, env) {
  const connectionId = cleanCredential(
    request.headers.get(REALTIME_CONNECTION_ID_HEADER),
    128
  );

  const connectionToken = cleanCredential(
    request.headers.get(REALTIME_CONNECTION_TOKEN_HEADER),
    512
  );

  if (!connectionId || !connectionToken) {
    return {
      response: jsonError("missing_connection_credentials", 401),
    };
  }

  return authenticateConnectionBody(
    {
      connection_id: connectionId,
      connection_token: connectionToken,
    },
    env
  );
}

// ================================================================
// KICK WEBHOOK RECEIVER
// ================================================================

async function handleKickWebhook(request, env) {
  if (request.method === "GET") {
    return Response.json(
      {
        status: "ok",
        service: "SleepySource Kick Webhook",
        signature_verification: true,
        endpoint: KICK_WEBHOOK_PATH,
      },
      { headers: noStoreHeaders() }
    );
  }

  if (request.method !== "POST") {
    return jsonError("method_not_allowed", 405);
  }

  if (!env.DB) {
    return jsonError("server_not_configured", 500);
  }

  await ensureSchema(env);

  const messageId = cleanWebhookHeader(
    request.headers.get("Kick-Event-Message-Id"),
    128
  );
  const subscriptionId = cleanWebhookHeader(
    request.headers.get("Kick-Event-Subscription-Id"),
    128
  );
  const signature = cleanWebhookHeader(
    request.headers.get("Kick-Event-Signature"),
    1024
  );
  const messageTimestamp = cleanWebhookHeader(
    request.headers.get("Kick-Event-Message-Timestamp"),
    128
  );
  const eventType = cleanWebhookHeader(
    request.headers.get("Kick-Event-Type"),
    128
  );
  const eventVersion = cleanWebhookHeader(
    request.headers.get("Kick-Event-Version"),
    32
  );

  if (
    !messageId ||
    !subscriptionId ||
    !signature ||
    !messageTimestamp ||
    !eventType ||
    !eventVersion
  ) {
    return jsonError("missing_webhook_headers", 400);
  }

  if (Number.isNaN(Date.parse(messageTimestamp))) {
    return jsonError("invalid_webhook_timestamp", 400);
  }

  const rawBody = await request.text();

  if (!rawBody || rawBody.length > 1_000_000) {
    return jsonError("invalid_webhook_body", 400);
  }

  const signedPayload = `${messageId}.${messageTimestamp}.${rawBody}`;

  let signatureValid = false;

  try {
    signatureValid = await verifyKickWebhookSignature(
      signedPayload,
      signature
    );
  } catch (error) {
    console.error(
      "Kick webhook verification failed:",
      safeErrorMessage(error)
    );

    // A temporary public-key lookup problem should be retried by Kick.
    return jsonError("webhook_verification_unavailable", 503);
  }

  if (!signatureValid) {
    return jsonError("invalid_webhook_signature", 401);
  }

  // Parse only after the signature has been verified.
  let parsedPayload;

  try {
    parsedPayload = JSON.parse(rawBody);
  } catch {
    return jsonError("invalid_webhook_json", 400);
  }

  const receivedAt = unixNow();

  // Store the verified webhook and queue its desktop delivery in one D1
  // transaction. If the subscription mapping is temporarily unavailable,
  // the poll endpoint later repairs the missing queue row from the stored event.
  const results = await env.DB.batch([
    env.DB.prepare(
      `
      INSERT OR IGNORE INTO kick_webhook_events (
        message_id,
        subscription_id,
        event_type,
        event_version,
        event_timestamp,
        payload_json,
        received_at,
        processed_at
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, NULL)
      `
    ).bind(
      messageId,
      subscriptionId,
      eventType,
      eventVersion,
      messageTimestamp,
      rawBody,
      receivedAt
    ),

    env.DB.prepare(
      `
      INSERT OR IGNORE INTO desktop_event_deliveries (
        message_id,
        connection_id,
        status,
        lease_id,
        lease_expires_at,
        attempt_count,
        last_attempt_at,
        created_at,
        updated_at,
        acked_at
      )
      SELECT
        ?,
        connection_id,
        'pending',
        NULL,
        NULL,
        0,
        NULL,
        ?,
        ?,
        NULL
      FROM kick_event_subscriptions
      WHERE subscription_id = ?
      LIMIT 1
      `
    ).bind(
      messageId,
      receivedAt,
      receivedAt,
      subscriptionId
    ),
  ]);

  const inserted = Number(results[0]?.meta?.changes || 0) === 1;
  const queued = Number(results[1]?.meta?.changes || 0) === 1;

  let realtimeSent = 0;

  // D1 remains the source of truth. Real-time delivery is an acceleration
  // path only: a Durable Object/WebSocket failure never loses the event.
  if (inserted && queued && env.REALTIME) {
    try {
      const delivery = await env.DB.prepare(
        `
        SELECT connection_id
        FROM desktop_event_deliveries
        WHERE message_id = ?
        LIMIT 1
        `
      )
        .bind(messageId)
        .first();

      if (delivery?.connection_id) {
        const stub = env.REALTIME.getByName(String(delivery.connection_id));

        const pushResult = await stub.pushEvent({
          message_id: messageId,
          event_type: eventType,
          event_version: eventVersion,
          event_timestamp: messageTimestamp,
          received_at: receivedAt,
          payload: parsedPayload,
        });

        realtimeSent = Number(pushResult?.sent || 0);
      }
    } catch (error) {
      console.error(
        "Realtime webhook push failed; D1 fallback preserved:",
        safeErrorMessage(error)
      );
    }
  }

  // Always acknowledge a valid duplicate. Kick-Event-Message-Id is the
  // idempotency key, so replayed deliveries do not create duplicate events.
  return Response.json(
    {
      status: "ok",
      accepted: true,
      duplicate: !inserted,
      queued,
      realtime_sent: realtimeSent,
    },
    {
      status: 200,
      headers: noStoreHeaders(),
    }
  );
}

// ================================================================
// KICK WEBHOOK SIGNATURE VERIFICATION
// ================================================================

async function verifyKickWebhookSignature(signedPayload, base64Signature) {
  const publicKey = await getKickWebhookPublicKey();
  const signatureBytes = base64ToBytes(base64Signature);
  const payloadBytes = new TextEncoder().encode(signedPayload);

  return crypto.subtle.verify(
    { name: "RSASSA-PKCS1-v1_5" },
    publicKey,
    signatureBytes,
    payloadBytes
  );
}

async function getKickWebhookPublicKey() {
  const now = unixNow();

  if (
    kickPublicKeyCache &&
    kickPublicKeyCachedAt > now - KICK_PUBLIC_KEY_CACHE_SECONDS
  ) {
    return kickPublicKeyCache;
  }

  const response = await fetch(KICK_PUBLIC_KEY_URL, {
    method: "GET",
    headers: { Accept: "application/json" },
  });

  if (!response.ok) {
    throw new Error(`Kick public key request failed: HTTP ${response.status}`);
  }

  const data = await response.json();
  const pem = String(data?.data?.public_key || "").trim();

  if (!pem) {
    throw new Error("Kick public key response did not contain a public key");
  }

  const importedKey = await importRsaPublicKeyFromPem(pem);
  kickPublicKeyCache = importedKey;
  kickPublicKeyCachedAt = now;

  return importedKey;
}

async function importRsaPublicKeyFromPem(pem) {
  const base64 = pem
    .replace(/-----BEGIN PUBLIC KEY-----/g, "")
    .replace(/-----END PUBLIC KEY-----/g, "")
    .replace(/\s+/g, "");

  const der = base64ToBytes(base64);

  return crypto.subtle.importKey(
    "spki",
    der,
    {
      name: "RSASSA-PKCS1-v1_5",
      hash: "SHA-256",
    },
    false,
    ["verify"]
  );
}

function cleanWebhookHeader(value, maxLength) {
  if (typeof value !== "string") {
    return "";
  }

  const cleaned = value.trim();

  if (!cleaned || cleaned.length > maxLength) {
    return "";
  }

  return cleaned;
}

// ================================================================
// SCHEMA
// ================================================================

async function ensureSchema(env) {
  if (!schemaReadyPromise) {
    schemaReadyPromise = env.DB.batch([
      env.DB.prepare(
        `
        CREATE TABLE IF NOT EXISTS oauth_sessions (
          session_id TEXT PRIMARY KEY,
          connection_id TEXT NOT NULL,
          state TEXT NOT NULL UNIQUE,
          code_verifier TEXT NOT NULL,
          poll_token_hash TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT 'pending',
          error_code TEXT,
          created_at INTEGER NOT NULL,
          expires_at INTEGER NOT NULL,
          completed_at INTEGER
        )
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_oauth_sessions_expires_at
        ON oauth_sessions(expires_at)
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_oauth_sessions_connection_id
        ON oauth_sessions(connection_id)
        `
      ),

      env.DB.prepare(
        `
        CREATE TABLE IF NOT EXISTS kick_connections (
          connection_id TEXT PRIMARY KEY,
          kick_user_id TEXT NOT NULL,
          kick_username TEXT NOT NULL,
          access_token_enc TEXT NOT NULL,
          refresh_token_enc TEXT NOT NULL,
          token_type TEXT NOT NULL DEFAULT 'Bearer',
          token_expires_at INTEGER NOT NULL,
          scopes TEXT NOT NULL,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL,
          last_refresh_at INTEGER,
          revoked_at INTEGER
        )
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_kick_connections_user_id
        ON kick_connections(kick_user_id)
        `
      ),

      env.DB.prepare(
        `
        CREATE TABLE IF NOT EXISTS connection_credentials (
          connection_id TEXT PRIMARY KEY,
          token_hash TEXT NOT NULL,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        )
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_connection_credentials_token_hash
        ON connection_credentials(token_hash)
        `
      ),

      env.DB.prepare(
        `
        CREATE TABLE IF NOT EXISTS kick_event_subscriptions (
          subscription_id TEXT PRIMARY KEY,
          connection_id TEXT NOT NULL,
          broadcaster_user_id TEXT NOT NULL,
          event_type TEXT NOT NULL,
          event_version INTEGER NOT NULL,
          method TEXT NOT NULL DEFAULT 'webhook',
          remote_created_at TEXT,
          remote_updated_at TEXT,
          synced_at INTEGER NOT NULL
        )
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_kick_event_subscriptions_connection
        ON kick_event_subscriptions(connection_id)
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_kick_event_subscriptions_event
        ON kick_event_subscriptions(event_type, event_version)
        `
      ),

      env.DB.prepare(
        `
        CREATE TABLE IF NOT EXISTS kick_webhook_events (
          message_id TEXT PRIMARY KEY,
          subscription_id TEXT NOT NULL,
          event_type TEXT NOT NULL,
          event_version TEXT NOT NULL,
          event_timestamp TEXT NOT NULL,
          payload_json TEXT NOT NULL,
          received_at INTEGER NOT NULL,
          processed_at INTEGER
        )
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_kick_webhook_events_type
        ON kick_webhook_events(event_type)
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_kick_webhook_events_received_at
        ON kick_webhook_events(received_at)
        `
      ),

      env.DB.prepare(
        `
        CREATE TABLE IF NOT EXISTS desktop_event_deliveries (
          message_id TEXT PRIMARY KEY,
          connection_id TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT 'pending',
          lease_id TEXT,
          lease_expires_at INTEGER,
          attempt_count INTEGER NOT NULL DEFAULT 0,
          last_attempt_at INTEGER,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL,
          acked_at INTEGER
        )
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_desktop_event_deliveries_connection_status
        ON desktop_event_deliveries(connection_id, status, created_at)
        `
      ),

      env.DB.prepare(
        `
        CREATE INDEX IF NOT EXISTS idx_desktop_event_deliveries_lease
        ON desktop_event_deliveries(connection_id, lease_expires_at)
        `
      ),
    ]).catch((error) => {
      schemaReadyPromise = null;
      throw error;
    });
  }

  return schemaReadyPromise;
}

// ================================================================
// CONFIGURATION
// ================================================================

function isConfigured(env) {
  return Boolean(
    env.KICK_CLIENT_ID &&
      env.KICK_CLIENT_SECRET &&
      env.KICK_REDIRECT_URI &&
      env.TOKEN_ENCRYPTION_KEY &&
      env.DB
  );
}

// ================================================================
// PERSISTENT CONNECTION AUTH
// ================================================================

async function authenticateConnectionRequest(request, env) {
  const body = await readJson(request);

  if (!body) {
    return { response: jsonError("invalid_json", 400) };
  }

  return authenticateConnectionBody(body, env);
}

async function authenticateConnectionBody(body, env) {
  const connectionId = cleanCredential(body.connection_id, 128);
  const connectionToken = cleanCredential(
    body.connection_token || body.poll_token,
    512
  );

  if (!connectionId || !connectionToken) {
    return {
      response: jsonError("missing_connection_credentials", 400),
    };
  }

  const tokenHash = await sha256Base64Url(connectionToken);

  const connection = await env.DB.prepare(
    `
    SELECT
      kc.connection_id,
      kc.kick_user_id,
      kc.kick_username,
      kc.access_token_enc,
      kc.refresh_token_enc,
      kc.token_type,
      kc.token_expires_at,
      kc.scopes,
      kc.created_at,
      kc.updated_at,
      kc.last_refresh_at,
      kc.revoked_at
    FROM kick_connections kc

    INNER JOIN connection_credentials cc
      ON cc.connection_id = kc.connection_id

    WHERE kc.connection_id = ?
      AND cc.token_hash = ?

    LIMIT 1
    `
  )
    .bind(connectionId, tokenHash)
    .first();

  if (!connection) {
    return {
      response: jsonError("invalid_connection_credentials", 401),
    };
  }

  return { connection };
}

// ================================================================
// AUTOMATIC TOKEN REFRESH
// ================================================================

async function ensureFreshKickConnection(env, connection, force) {
  const now = unixNow();

  if (
    !force &&
    Number(connection.token_expires_at) > now + REFRESH_EARLY_SECONDS
  ) {
    return {
      kind: "connected",
      refreshed: false,
      connection,
    };
  }

  const claim = await env.DB.prepare(
    `
    UPDATE kick_connections
    SET last_refresh_at = ?
    WHERE connection_id = ?
      AND revoked_at IS NULL
      AND (
        ? = 1
        OR token_expires_at <= ?
      )
      AND (
        last_refresh_at IS NULL
        OR last_refresh_at < ?
      )
    `
  )
    .bind(
      now,
      connection.connection_id,
      force ? 1 : 0,
      now + REFRESH_EARLY_SECONDS,
      now - REFRESH_LOCK_SECONDS
    )
    .run();

  if (!claim.success || Number(claim.meta?.changes || 0) !== 1) {
    const current = await loadConnection(env, connection.connection_id);

    if (!current) {
      return { kind: "temporary_failure", connection };
    }

    if (
      !force &&
      Number(current.token_expires_at) > now + REFRESH_EARLY_SECONDS
    ) {
      return {
        kind: "connected",
        refreshed: true,
        connection: current,
      };
    }

    return {
      kind: "refreshing",
      connection: current,
    };
  }

  let refreshToken;

  try {
    refreshToken = await decryptSecret(
      connection.refresh_token_enc,
      env.TOKEN_ENCRYPTION_KEY,
      connection.connection_id
    );
  } catch (error) {
    console.error("Refresh token decrypt failed:", safeErrorMessage(error));
    return { kind: "reconnect_required", connection };
  }

  const refreshBody = new URLSearchParams();
  refreshBody.set("grant_type", "refresh_token");
  refreshBody.set("client_id", env.KICK_CLIENT_ID);
  refreshBody.set("client_secret", env.KICK_CLIENT_SECRET);
  refreshBody.set("refresh_token", refreshToken);

  let response;

  try {
    response = await fetch(KICK_TOKEN_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Accept: "application/json",
      },
      body: refreshBody.toString(),
    });
  } catch (error) {
    console.error("Kick refresh network failure:", safeErrorMessage(error));
    return { kind: "temporary_failure", connection };
  }

  if (!response.ok) {
    console.error("Kick refresh failed with HTTP", response.status);

    if (response.status === 400 || response.status === 401 || response.status === 403) {
      return { kind: "reconnect_required", connection };
    }

    return { kind: "temporary_failure", connection };
  }

  let tokenData;

  try {
    tokenData = await response.json();
  } catch {
    return { kind: "temporary_failure", connection };
  }

  const expiresIn = Number(tokenData.expires_in);

  if (
    !tokenData.access_token ||
    !tokenData.refresh_token ||
    !Number.isFinite(expiresIn) ||
    expiresIn <= 0
  ) {
    return { kind: "temporary_failure", connection };
  }

  const accessTokenEncrypted = await encryptSecret(
    tokenData.access_token,
    env.TOKEN_ENCRYPTION_KEY,
    connection.connection_id
  );

  const refreshTokenEncrypted = await encryptSecret(
    tokenData.refresh_token,
    env.TOKEN_ENCRYPTION_KEY,
    connection.connection_id
  );

  const tokenExpiresAt = now + Math.floor(expiresIn);
  const scopes = normalizeScopes(tokenData.scope, connection.scopes);
  const tokenType = String(tokenData.token_type || connection.token_type || "Bearer");

  await env.DB.prepare(
    `
    UPDATE kick_connections
    SET
      access_token_enc = ?,
      refresh_token_enc = ?,
      token_type = ?,
      token_expires_at = ?,
      scopes = ?,
      updated_at = ?,
      last_refresh_at = ?
    WHERE connection_id = ?
      AND revoked_at IS NULL
    `
  )
    .bind(
      accessTokenEncrypted,
      refreshTokenEncrypted,
      tokenType,
      tokenExpiresAt,
      scopes,
      now,
      now,
      connection.connection_id
    )
    .run();

  const updated = await loadConnection(env, connection.connection_id);

  return {
    kind: "connected",
    refreshed: true,
    connection:
      updated || {
        ...connection,
        token_expires_at: tokenExpiresAt,
        scopes,
        token_type: tokenType,
      },
  };
}

// ================================================================
// LOAD CONNECTION
// ================================================================

async function loadConnection(env, connectionId) {
  return env.DB.prepare(
    `
    SELECT
      connection_id,
      kick_user_id,
      kick_username,
      access_token_enc,
      refresh_token_enc,
      token_type,
      token_expires_at,
      scopes,
      created_at,
      updated_at,
      last_refresh_at,
      revoked_at
    FROM kick_connections
    WHERE connection_id = ?
    LIMIT 1
    `
  )
    .bind(connectionId)
    .first();
}

// ================================================================
// SAVE PERSISTENT CREDENTIAL
// ================================================================

async function upsertConnectionCredential(env, connectionId, tokenHash, now) {
  await env.DB.prepare(
    `
    INSERT INTO connection_credentials (
      connection_id,
      token_hash,
      created_at,
      updated_at
    )
    VALUES (?, ?, ?, ?)

    ON CONFLICT(connection_id)
    DO UPDATE SET
      token_hash = excluded.token_hash,
      updated_at = excluded.updated_at
    `
  )
    .bind(connectionId, tokenHash, now, now)
    .run();
}

// ================================================================
// PUBLIC CONNECTION RESPONSE
// ================================================================

function publicConnection(connection) {
  return {
    connection_id: String(connection.connection_id),
    kick_user_id: String(connection.kick_user_id),
    kick_username: String(connection.kick_username),
    scopes: String(connection.scopes || "")
      .split(/\s+/)
      .filter(Boolean),
    token_expires_at: Number(connection.token_expires_at),
    last_refresh_at:
      connection.last_refresh_at == null
        ? null
        : Number(connection.last_refresh_at),
    revoked_at:
      connection.revoked_at == null ? null : Number(connection.revoked_at),
  };
}

// ================================================================
// SESSION FAILURE
// ================================================================

async function markSessionFailed(env, sessionId, errorCode) {
  await env.DB.prepare(
    `
    UPDATE oauth_sessions
    SET
      status = 'failed',
      code_verifier = '',
      error_code = ?,
      completed_at = ?
    WHERE session_id = ?
    `
  )
    .bind(errorCode, unixNow(), sessionId)
    .run();
}

// ================================================================
// RANDOM + SHA256
// ================================================================

function randomBase64Url(byteLength) {
  const bytes = new Uint8Array(byteLength);
  crypto.getRandomValues(bytes);
  return base64UrlEncode(bytes);
}

async function sha256Base64Url(value) {
  const data = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest("SHA-256", data);
  return base64UrlEncode(new Uint8Array(digest));
}

// ================================================================
// AES-GCM ENCRYPT / DECRYPT
// ================================================================

async function encryptSecret(plaintext, base64Key, connectionId) {
  const keyBytes = base64ToBytes(base64Key);

  if (keyBytes.length !== 32) {
    throw new Error("Invalid encryption key length");
  }

  const key = await crypto.subtle.importKey(
    "raw",
    keyBytes,
    { name: "AES-GCM" },
    false,
    ["encrypt"]
  );

  const iv = new Uint8Array(12);
  crypto.getRandomValues(iv);

  const encrypted = await crypto.subtle.encrypt(
    {
      name: "AES-GCM",
      iv,
      additionalData: new TextEncoder().encode(connectionId),
      tagLength: 128,
    },
    key,
    new TextEncoder().encode(plaintext)
  );

  return [
    "v1",
    base64UrlEncode(iv),
    base64UrlEncode(new Uint8Array(encrypted)),
  ].join(".");
}

async function decryptSecret(value, base64Key, connectionId) {
  const parts = String(value).split(".");

  if (parts.length !== 3 || parts[0] !== "v1") {
    throw new Error("Unsupported encrypted value format");
  }

  const keyBytes = base64ToBytes(base64Key);

  if (keyBytes.length !== 32) {
    throw new Error("Invalid encryption key length");
  }

  const key = await crypto.subtle.importKey(
    "raw",
    keyBytes,
    { name: "AES-GCM" },
    false,
    ["decrypt"]
  );

  const decrypted = await crypto.subtle.decrypt(
    {
      name: "AES-GCM",
      iv: base64UrlToBytes(parts[1]),
      additionalData: new TextEncoder().encode(connectionId),
      tagLength: 128,
    },
    key,
    base64UrlToBytes(parts[2])
  );

  return new TextDecoder().decode(decrypted);
}

// ================================================================
// BASE64 HELPERS
// ================================================================

function base64ToBytes(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);

  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }

  return bytes;
}

function base64UrlToBytes(value) {
  let normalized = String(value)
    .replace(/-/g, "+")
    .replace(/_/g, "/");

  while (normalized.length % 4) {
    normalized += "=";
  }

  return base64ToBytes(normalized);
}

function base64UrlEncode(bytes) {
  let binary = "";

  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }

  return btoa(binary)
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/g, "");
}

// ================================================================
// SCOPES
// ================================================================

function normalizeScopes(scope, fallback) {
  if (Array.isArray(scope)) {
    return scope.join(" ");
  }

  const value = String(scope || "").trim();
  return value || String(fallback || "");
}

// ================================================================
// REQUEST HELPERS
// ================================================================

async function readJson(request) {
  try {
    return await request.json();
  } catch {
    return null;
  }
}

function cleanCredential(value, maxLength) {
  if (typeof value !== "string") {
    return "";
  }

  const cleaned = value.trim();

  if (!cleaned || cleaned.length > maxLength) {
    return "";
  }

  return cleaned;
}

function unixNow() {
  return Math.floor(Date.now() / 1000);
}

function noStoreHeaders() {
  return { "Cache-Control": "no-store" };
}

function jsonError(code, status) {
  return Response.json(
    { status: "error", error: code },
    { status, headers: noStoreHeaders() }
  );
}

