// ================================================================
// SLEEPYSOURCE REAL-TIME DURABLE OBJECT
// ================================================================

export class SleepySourceRealtime extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
  }

  async fetch(request) {
    const upgrade = String(request.headers.get("Upgrade") || "").toLowerCase();

    if (upgrade !== "websocket") {
      return new Response("WebSocket upgrade required.", {
        status: 426,
        headers: { Upgrade: "websocket" },
      });
    }

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);

    // Hibernation API: Cloudflare can evict this Durable Object from memory
    // while keeping the desktop WebSocket alive.
    this.ctx.acceptWebSocket(server, ["desktop"]);

    const attachment = {
      connection_id: this.ctx.id.name || null,
      connected_at: Date.now(),
    };

    server.serializeAttachment(attachment);

    server.send(
      JSON.stringify({
        type: "ready",
        realtime: true,
        connection_id: attachment.connection_id,
        connected_at: attachment.connected_at,
        fallback_queue: true,
      })
    );

    return new Response(null, {
      status: 101,
      webSocket: client,
    });
  }

  async pushEvent(event) {
    const message = JSON.stringify({
      type: "kick_event",
      delivery: "realtime",
      event,
    });

    let sent = 0;

    for (const ws of this.ctx.getWebSockets("desktop")) {
      if (ws.readyState !== WebSocket.OPEN) {
        continue;
      }

      try {
        ws.send(message);
        sent += 1;
      } catch {
        // The D1 queue is the durable fallback. A single broken socket must
        // never cause the verified Kick webhook request to fail.
      }
    }

    return { sent };
  }

  async getConnectionCount() {
    return this.ctx
      .getWebSockets("desktop")
      .filter((ws) => ws.readyState === WebSocket.OPEN)
      .length;
  }

  async disconnectAll(reason = "Connection closed") {
    let closed = 0;

    for (const ws of this.ctx.getWebSockets("desktop")) {
      try {
        ws.close(1000, String(reason).slice(0, 123));
        closed += 1;
      } catch {
      }
    }

    return { closed };
  }

  async webSocketMessage(ws, message) {
    if (typeof message !== "string") {
      return;
    }

    if (message === "ping") {
      ws.send("pong");
      return;
    }

    try {
      const data = JSON.parse(message);

      if (data?.type === "ping") {
        ws.send(
          JSON.stringify({
            type: "pong",
            at: Date.now(),
          })
        );
      }
    } catch {
      // Unknown client messages are intentionally ignored. Event ACKs remain
      // authenticated through /kick/events/delivery/ack.
    }
  }

  async webSocketClose(ws, code, reason) {
    // With the current compatibility date Cloudflare completes the close
    // handshake automatically. Calling close here is still safe.
    try {
      ws.close(code, reason);
    } catch {
    }
  }

  async webSocketError(ws) {
    try {
      ws.close(1011, "WebSocket error");
    } catch {
    }
  }
}

